 } from "./commitSearchCache";

 const commitSearchResult: CommitData = {
   found: true,
   commits: [
     {
       message: "Initial commit",
       date: "2024-01-02T00:00:00Z",
       html_url: "https://github.com/octo/repo/commit/abcdef123456",
       sha: "abcdef123456",
