1. "use client";
2. 
3. import type { FormEvent } from "react";
4. import { useEffect, useRef, useState, useTransition } from "react";
5. import Link from "next/link";
6. import { FaGithub } from "react-icons/fa";
7. import { getCommits } from "./actions";
8. import type { CommitData } from "./commitTypes";
9. import { trackAppEvent } from "./home/analytics";
10. import { EXAMPLE_USERNAMES, MAX_RECENT_SEARCHES } from "./home/constants";
11. import { isRecoverableClipboardWriteError } from "./home/browserErrors";
12. import SearchErrorState from "./home/SearchErrorState";
13. import SearchForm from "./home/SearchForm";
14. import SearchResults from "./home/SearchResults";
15. import SearchShortcutSection from "./home/SearchShortcutSection";
16. import {
17.   clearStoredRecentSearches,
18.   getStoredRecentSearches,
19.   saveStoredRecentSearches,
20. } from "./home/recentSearches";
21. import {
22.   buildResultShareText,
23.   clearSharedSearchUrl,
24.   getInitialSharedUsername,
25.   updateSharedSearchUrl,
26. } from "./home/sharedSearch";
27. import { getUsernameValidationMessage, normalizeGitHubUsername } from "./username";
28. const APP_RELEASE = process.env.NEXT_PUBLIC_APP_RELEASE ?? "local";
29. const APP_RELEASE_URL = process.env.NEXT_PUBLIC_APP_RELEASE_URL ?? "";
30. 
31. export default function Home() {
32.   const [username, setUsername] = useState(getInitialSharedUsername);
33.   const [result, setResult] = useState<CommitData | null>(null);
34.   const [lastSearchedUsername, setLastSearchedUsername] = useState("");
35.   const [recentSearches, setRecentSearches] = useState<string[]>([]);
36.   const [shareStatus, setShareStatus] = useState("");
37.   const [isPending, startTransition] = useTransition();
38.   const searchInputRef = useRef<HTMLInputElement>(null);
39.   const searchRunnerRef = useRef<
40.     (searchUsername: string, options?: { updateUrl?: boolean }) => void
41.   >(() => undefined);
42. 
43.   useEffect(() => {
44.     const loadRecentSearches = window.setTimeout(() => {
45.       setRecentSearches(getStoredRecentSearches());
46.     }, 0);
47. 
48.     return () => window.clearTimeout(loadRecentSearches);
49.   }, []);
50. 
51.   useEffect(() => {
52.     if (!result?.found) {
53.       searchInputRef.current?.focus();
54.     }
55.   }, [result?.found]);
56. 
57.   const rememberRecentSearch = (searchedUsername: string) => {
58.     setRecentSearches((currentSearches) => {
59.       const nextSearches = [
60.         searchedUsername,
61.         ...currentSearches.filter(
62.           (search) => search.toLowerCase() !== searchedUsername.toLowerCase(),
63.         ),
64.       ].slice(0, MAX_RECENT_SEARCHES);
65. 
66.       saveStoredRecentSearches(nextSearches);
67.       return nextSearches;
68.     });
69.   };
70. 
71.   const clearRecentSearches = () => {
72.     setRecentSearches([]);
73.     clearStoredRecentSearches();
74.     focusSearchInput();
75.   };
76. 
77.   searchRunnerRef.current = (
78.    searchUsername: string,
79.    options: { updateUrl?: boolean } = {},
80.   ) => {
