    setShareStatus("");
    clearSharedSearchUrl();
    focusSearchInput();
   };

   const startNewSearch = () => {
    setResult(null);
    setUsername("");
    setLastSearchedUsername("");
    setSearchRequest(null);
    setShareStatus("");
    clearSharedSearchUrl();
    focusSearchInput();
